\label{prop:Schmidt-bound}
Let $\mathcal C\subseteq\mathrm{Sym}_n(q)$ be a symmetric $d$-code. If $d$ is odd, then
\begin{equation*}
|\mathcal C|\le\begin{cases}
q^{\,n(n-d+2)/2},& n-d \text{ even},\\[1mm]
q^{\,(n+1)(n-d+1)/2},& n-d \text{ odd}.
\end{cases}
\end{equation*}
If $d$ is even, the same bounds hold under the additional assumption that $\mathcal C$ is additive.

\label{prop:quotient-construction}
Let $q$ be odd and let $S\subseteq\mathbb F_q^4$ satisfy
\begin{equation}
Q(x-y)\neq0\qquad\text{for all distinct }x,y\in S.
\label{eq:anisotropic-differences}
\end{equation}
Then $\mathcal{C}_S:=\pi^{-1}(S)$ is a symmetric $2$-code in $\mathrm{Sym}_3(q)$, and
\begin{equation*}
|\mathcal{C}_S|=q^2|S|.
\end{equation*}

\label{prop:quotient-construction iff}
Let $q$ be odd. Let $\mathcal{S}$ be a union of cosets of $H_\delta$, $\mathcal{S}$ is a symmetric $2$-code if and only if 
\begin{equation*}
    Q(x-y)\neq0\qquad\text{for all distinct }x,y\in \pi (\mathcal{S}).
\end{equation*}

\label{lem:affine-chart}
Let $q$ be odd. The points of $Q^-(5,q)$ that are not orthogonal to $P_\infty=\langle (1,0,0,0,0,0)\rangle$ are in one-to-one correspondence with the vectors of $\mathbb F_q^4$. More precisely, the correspondence is
\begin{equation*}
x\in \mathbb F_q^4\longmapsto P_x=\left\langle\bigl(Q(x),x,1\bigr)\right\rangle \in Q^-(5,q).
\end{equation*}
Moreover, for $x,y\in\mathbb F_q^4$,
\begin{equation}
P_x\perp P_y\quad\Longleftrightarrow\quad Q(x-y)=0.
\label{eq:orthogonality-difference}
\end{equation}

\label{prop:partial-ovoid-input}
Let $q$ be odd. Suppose that $Q^-(5,q)$ contains a partial ovoid $\mathcal O$ of size $m$. Then there exists a set $S\subseteq\mathbb F_q^4$ of size $|S|=m-1$, such that
\[
Q(x-y)\neq0\qquad\text{for every distinct }x,y\in S.
\]
Consequently,
\begin{equation*}
A_q^{\rm sym}(3,2)\ge q^2(m-1).
\end{equation*}

\label{cor:main-symmetric}
For every odd prime power $q$,
\begin{equation*}
A_q^{\rm sym}(3,2)\ge q^4+2q^3.
\end{equation*}
Moreover, the code obtained in this way is non-additive.

\label{prop:fibre-partial-ovoid-equivalence}
Let $q$ be odd. The maximum size of a symmetric $2$-code in $\mathrm{Sym}_3(q)$ which is a union of complete cosets of $H_\delta$ is
\begin{equation*}
    q^2\bigl(\mu^-(5,q)-1\bigr).
\end{equation*}
In particular,
\[ 
A_q^{\rm sym}(3,2)\ge q^2\bigl(\mu^-(5,q)-1\bigr).
\]

\label{thm:block-product}
Let $\mathcal C\subseteq\mathrm{Sym}_{n_1}(q),\mathcal D\subseteq\mathrm{Sym}_{n_2}(q)$
be symmetric $2$-codes. Then
\begin{equation}
\mathcal C\star\mathcal D = \left\{\begin{pmatrix}
A&X\\
X^T&B
\end{pmatrix}\,:\,A\in\mathcal C,\;B\in\mathcal D,\;X\in\mathbb F_q^{\,n_1\times n_2}\right\}\subseteq\mathrm{Sym}_{n_1+n_2}(q)
\label{eq:block-product}
\end{equation}
is a symmetric $2$-code.  Moreover,
\begin{equation*}
|\mathcal C\star\mathcal D| = q^{n_1n_2}|\mathcal C||\mathcal D|.
\end{equation*}
Consequently,
\begin{equation*}
A_q^{\rm sym}(n_1+n_2,2)
\ge
q^{n_1n_2}
A_q^{\rm sym}(n_1,2)
A_q^{\rm sym}(n_2,2).
\end{equation*}

\label{prop:H}
There exist $\alpha,\beta\in\mathbb F_q$ such that

\begin{equation*}
\mathcal H_{\alpha,\beta}=\left\{
\begin{pmatrix}
a&b\\
b&\alpha a+\beta b
\end{pmatrix}\,:\,a,b\in\mathbb F_q\right\}\subseteq\mathrm{Sym}_2(q)
\end{equation*}

is an additive symmetric $2$-code of cardinality $q^2$.

\label{cor:two-dimensional-recursion}

For every $n\ge1$,
\begin{equation*}
A_q^{\rm sym}(n+2,2)\ge q^{2n+2}A_q^{\rm sym}(n,2).
\end{equation*}
More precisely, if $\mathcal C_n\subseteq\mathrm{Sym}_n(q)$ is a symmetric $2$-code, then
\begin{equation*}
\mathcal C_{n+2}=\left\{
\begin{pmatrix}
A&X\\
X^T&H
\end{pmatrix}\,:\,A\in\mathcal C_n,\;X\in\mathbb F_q^{\,n\times2},\;H\in\mathcal H_{\alpha,\beta}\right\}
\end{equation*}
is a symmetric $2$-code with $|\mathcal C_{n+2}|=q^{2n+2}|\mathcal C_n|$.

\label{thm:propagation-seed}
Suppose that there exists a symmetric $2$-code $\mathcal C_3\subseteq\mathrm{Sym}_3(q)$ of size $M$.  Then, for every odd integer $n\ge3$,
\begin{equation*}
A_q^{\rm sym}(n,2)\ge q^{(n^2-9)/2}M.
\end{equation*}

\label{cor:all-symmetric}
    Let $q,n\geq 3$ with $n$ odd. Then
    \begin{equation*}
        A_q^{\rm sym}(n,2) \ge q^{(n^2-1)/2}+q^{(n^2-3)/2}+q^{(n^2-9)/2}.
    \end{equation*}

Since $q\geq3$ there exists a Cossidente-Marino-Pavese code $\mathcal{C}_{\rm CMP}\subseteq \mathrm{Sym}_3(q)$. Such a code is a symmetric $2$-code with cardinality $|\mathcal{C}_{\rm CMP}|=q^4+q^3+1$, therefore, applying Theorem \ref{thm:propagation-seed}, we get
    \begin{equation*}
        A_q^{\rm sym}(n,2) \ge q^{(n^2-9)/2}(q^4+q^3+1)= q^{(n^2-1)/2}+q^{(n^2-3)/2}+q^{(n^2-9)/2}.
    \end{equation*}

\label{cor:partial-ovoid-propagation}
Let $q$ be odd and suppose that $Q^-(5,q)$ contains a partial ovoid of size $m$.  Then, for every odd $n\ge3$,
\begin{equation}
A_q^{\rm sym}(n,2) \ge q^{(n^2-5)/2}(m-1).
\label{eq:partial-ovoid-all-odd}
\end{equation}

\label{cor:all-odd-symmetric}
Let $q$ and $n\ge3$ be odd.  Then
\begin{equation*}
A_q^{\rm sym}(n,2)\ge q^{(n^2-1)/2}+2q^{(n^2-3)/2}.
\end{equation*}

For odd $n$ and $q\geq 3$ construct symmetric $2$-codes in $\mathrm{Sym}_n(q)$ that improve upon
\[
A_q^{\rm sym}(n,2)\geq q^{(n^2-1)/2}+2q^{(n^2-3)/2},\qquad \text{when $q$ is odd},
\]
\begin{equation*}
    A_q^{\rm sym}(n,2) \ge q^{(n^2-1)/2}+q^{(n^2-3)/2}+q^{(n^2-9)/2},\qquad \text{when $q$ is even.}
\end{equation*}
